"""Build shared data, static navigation and the CSS bundle. No dependencies."""
import json,re,html
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
CSS=['tokens.css','base.css','components.css','glacier.css']
(ROOT/'style.css').write_text('/* Generated by scripts/build_site.py. Edit tokens.css, base.css or components.css. */\n'+'\n'.join((ROOT/f).read_text() for f in CSS))
data=json.loads((ROOT/'products.json').read_text())
module='''(function(root) {
 const data=DATA;
 const locale={fr:'fr-FR',en:'en-GB',pt:'pt-PT',es:'es-ES'};
 const money=(cents,lang)=>new Intl.NumberFormat(locale[lang]||locale.fr,{style:'currency',currency:'EUR',maximumFractionDigits:2}).format(cents/100);
 root.ScarlsProducts={...data,byName:name=>data.items.find(item=>item.name===name),catalogue:(lang='fr')=>data.groups.map((group,index)=>[group.labels[lang]||group.labels.fr,data.items.filter(item=>item.group===index).map(item=>[item.name,item.dose,item.descriptions[lang]||item.descriptions.fr,money(item.priceCents,lang),item.previousPriceCents?money(item.previousPriceCents,lang):undefined])])};
})(typeof window!=='undefined'?window:globalThis);
'''.replace('DATA',json.dumps(data,ensure_ascii=False,separators=(',',':')))
(ROOT/'products.js').write_text(module+'\n'+(ROOT/'catalogue-sync.js').read_text())
f=ROOT/'home.js';s=f.read_text();copy=json.loads((ROOT/'home-copy.json').read_text());s=re.sub(r'/\* HOME_COPY_START \*/.*?/\* HOME_COPY_END \*/','/* HOME_COPY_START */\nconst HOME_COPY = '+json.dumps(copy,ensure_ascii=False,separators=(',',':'))+';\n/* HOME_COPY_END */',s,flags=re.S);f.write_text(s)
header=(ROOT/'partials/header.html').read_text().strip();footer=(ROOT/'partials/footer.html').read_text().strip()
for file in ['index.html','produits.html','apropos.html','livraison.html','contact.html','faq.html']:
 f=ROOT/file;s=f.read_text();nav=header.replace('href="'+file+'"','class="current" aria-current="page" href="'+file+'"',1) if file!='index.html' else header.replace('href="index.html">Accueil','class="current" aria-current="page" href="index.html">Accueil')
 # The first index.html link belongs to the brand: choose the nav link explicitly.
 nav=header.replace('<a href="'+file+'">','<a class="current" aria-current="page" href="'+file+'">')
 s=re.sub(r'<header class="site-header">.*?</header>',lambda m:nav,s,flags=re.S)
 s=re.sub(r'<footer>.*?</footer>',lambda m:footer,s,flags=re.S)
 # Static FAQ assistant is limited to public information pages.
 s=re.sub(r'\s*<link rel="stylesheet" href="assistant\.css[^\"]*">','',s)
 s=re.sub(r'\s*<script src="assistant(?:-data)?\.js[^\"]*"[^>]*></script>','',s)
 s=s.replace('</head>','  <link rel="stylesheet" href="assistant.css?v=20261031faq4">\n</head>')
 s=s.replace('</body>','  <script src="assistant-data.js?v=20261031faq4" defer></script>\n  <script src="assistant.js?v=20261031faq4" defer></script>\n</body>')
 f.write_text(s)
# Readable static catalogue remains available when JavaScript fails.
f=ROOT/'produits.html';s=f.read_text();cards=[]
for gi,group in enumerate(data['groups']):
 rows=[]
 for item in [x for x in data['items'] if x['group']==gi]:
  esc=lambda value:html.escape(str(value),quote=True)
  pic=f'<img src="{esc(item["image"])}" alt="{esc(item["name"])} — {esc(item["dose"])}" width="800" height="915" loading="lazy">' if item['image'] else f'<div class="product-image-pending"><strong>{esc(item["name"])}</strong><span>{esc(item["dose"])}</span><small>Visuel à venir</small></div>'
  rows.append(f'<article class="product-card" id="{esc(item["id"])}" style="--vial-backdrop:url({esc(item.get("backdrop","glacier-night.webp"))})"><div class="product-image">{pic}</div><div class="product-content"><h3 class="product-name">{esc(item["name"])}<span class="product-dose">{esc(item["dose"])}</span></h3><p class="product-use">{esc(item["descriptions"]["fr"])}</p><div class="product-bottom"><span class="price">{item["priceCents"]//100} €</span><a class="text-link" href="contact.html">Contact</a></div></div></article>')
 cards.append(f'<section class="product-group"><div class="group-heading"><h2>{html.escape(group["labels"]["fr"])}</h2><span>{len(rows)} référence(s)</span></div><div class="product-grid">'+''.join(rows)+'</div></section>')
markup='<div class="container" id="catalogue">'+''.join(cards)+'</div><!-- catalogue-end -->'
s=re.sub(r'<div(?: class="container")? id="catalogue">.*?</div><!-- catalogue-end -->',lambda m:markup,s,flags=re.S) if '<!-- catalogue-end -->' in s else s.replace('<div class="container" id="catalogue"></div>',markup.replace('<div id="catalogue">','<div class="container" id="catalogue">',1))
f.write_text(s)
print('Built shared components, CSS, product data and static catalogue.')

